function addStatus($msg, $type = 'info') {
    echo "<div class='status status--$type'>$msg</div>";
    @ob_flush();
    @flush();
}

function updateProgress($pct) {
    echo "<script>document.getElementById('progress').style.width='" . $pct . "%';</script>";
    @ob_flush();
    @flush();
}

