    // Preparar statement de inserción
    $sql = "INSERT INTO productos (nombre, marca, descripcion, descripcion_corta, imagen, categoria, tipo_olor, notas, notas_salida, notas_corazon, notas_fondo, emoji, transmite, ideal_para, duracion, intensidad, colores, precio, activo, destacado) VALUES (?, ?, ?, ?, ?, 'mujer', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, 1, 0)";
    $stmt = $pdo->prepare($sql);

    $insertados = 0;
    $errores = 0;
    $total = count($productos);

    foreach ($productos as $i => $p) {
        $pct = 10 + round(($i / $total) * 85);
        updateProgress($pct);
        
        try {
            $stmt->execute($p);
            $insertados++;
            if (($insertados % 10) == 0) {
                addStatus("Insertados $insertados de $total productos...", "ok");
            }
        } catch (PDOException $e) {
            $errores++;
            addStatus("Error insertando '{$p[0]}': " . $e->getMessage(), "error");
        }
    }

    updateProgress(95);
    addStatus("Importación completada: $insertados productos insertados, $errores errores.", $errores > 0 ? "warning" : "ok");
}

// Verificar total final
$finalCount = $pdo->query("SELECT COUNT(*) as total FROM productos WHERE categoria = 'mujer' AND activo = 1")->fetch()['total'];
